import React, { useContext } from 'react';
import { SocialMediaContext } from '../context/SocialMediaContext'; // Context import kelay ka bagha

function Home() {
    // Context destructuring
    const { posts, isLoading, error } = useContext(SocialMediaContext);

    // Jar context madhun values bhetat nastil, tar ithe check laavu shakta:
    // if (!isLoading && !posts) return <div>Loading...</div>;

    return (
        <div style={{ maxWidth: '650px', margin: '0 auto' }}>
            {isLoading && <p>Loading posts...</p>}
            {/* Baki che components */}
        </div>
    );
}

export default Home;
